insert into academy_lessons (section_id, sort, title, scenes) select (select id from academy_sections where slug = 'marketplace-with-claude'), 1, 'Your own listings, never the same ad twice', '[{"caption":"Sales > Marketing","say":"Your Marketing tab is the Facebook Marketplace tool for your own profile: what to post today, the kit for each car, the replies and your log.","visual":{"kind":"title","heading":"Sales > Marketing","text":"Your own profile, your own listings"}},{"caption":"A copy variant of your own","say":"Each car can have up to five live listings across the team, the owner''s included. Each listing is a different copy variant: its own title, description wording, photo order and cover photo.","visual":{"kind":"list","heading":"Your variant","items":["Its own title","Its own description wording","Its own photo order and cover","Claimed by you alone"]}},{"caption":"Claim, post, log","say":"Press Claim on a Today item, open its kit, post it on Facebook, then press Posted and paste the listing''s address. A claim you do not post within a day lets go by itself.","visual":{"kind":"steps","heading":"One car","items":["Claim the variant","Open the kit, download the photos","Post it on Facebook","Posted: paste the address"]}},{"caption":"The words","say":"Nothing a buyer reads says rent, rental or for rent. Every listing keeps the line: Daily and weekly bookings only, not for sale. The price is for one day.","visual":{"kind":"rule","heading":"The wording rule","text":"Never \"rent\" or \"rental\". Always \"Daily and weekly bookings only, not for sale\".","tone":"warn"}}]'::jsonb where not exists (select 1 from academy_lessons where section_id = (select id from academy_sections where slug = 'marketplace-with-claude') and sort = 1);
